INSERT INTO `artesanos` (`id`, `user_id`, `nombre`, `apellido`, `direccion_arte`, `telefono`, `historia_taller`, `foto_perfil`, `estado_validacion`, `created_at`, `updated_at`) VALUES (1, 3, 'Edwin', 'Quispe Huallpa', 'Galería Marqués & Valle de La Convención, Cusco', '+51 984 556 789', 'Con más de 28 años de trayectoria en el Centro Histórico de Cusco, Don Edwin Quispe lidera una red cooperativa que une a caficultores agroforestales de La Convención (Quillabamba) con maestros chocolateros y tejedores tradicionales. Su taller promueve el cultivo de cacao chuncho nativo orgánico y la preservación de telares de pedal andinos.', 'https://picsum.photos/seed/edwin-artesano/400/400', 1, '2026-11-17 17:48:03', '2026-11-17 17:48:03');
INSERT INTO `artesanos` (`id`, `user_id`, `nombre`, `apellido`, `direccion_arte`, `telefono`, `historia_taller`, `foto_perfil`, `estado_validacion`, `created_at`, `updated_at`) VALUES (2, 4, 'Marco Polo', 'Baca Palomino', 'Barrio de San Blas, Cusco', '+51 984 334 112', 'Heredero de cuatro generaciones de maestros orfebres e imagineros en el emblemático barrio de San Blas. Marco Polo Baca domina la técnica ancestral del cincelado, repujado y filigrana en plata 950, inspirándose en los retablos del barroco andino cusqueño y la iconografía solar incaica.', 'https://picsum.photos/seed/marcopolo-artesano/400/400', 1, '2026-11-17 17:48:03', '2026-11-17 17:48:03');
INSERT INTO `artesanos` (`id`, `user_id`, `nombre`, `apellido`, `direccion_arte`, `telefono`, `historia_taller`, `foto_perfil`, `estado_validacion`, `created_at`, `updated_at`) VALUES (3, 5, 'María', 'Huamán Condori', 'Chinchero & Mercado San Pedro, Cusco', '+51 984 778 990', 'Maestra tejedora quechua originaria de Chinchero y portavoz de la Asociación Munay Away en el Mercado Central de San Pedro. Dedicada al rescate de la iconografía "pallay" con lana 100% alpaca virgen hilada con rueca (pushka) y teñida exclusivamente con cochinilla, qolle, chilca y sales volcánicas andinas.', 'https://picsum.photos/seed/maria-artesana/400/400', 1, '2026-11-17 17:48:03', '2026-11-17 17:48:03');
INSERT INTO `productos` (`id`, `artesano_id`, `nombre_prod`, `descripcion_prod`, `categoria`, `subtipo`, `precio`, `stock`, `tamano`, `colores`, `puntuacion`, `materiales_origen`, `certificado_autenticidad_codigo`, `aprobado_hub`, `imagen_url`, `created_at`, `updated_at`, `en_oferta`, `precio_oferta`, `descuento_porcentaje`, `etiqueta_promocion`) VALUES (1, 1, 'Café Gourmet Geisha de Altura La Convención (250g)', 'Café de especialidad cosechado a mano a más de 1,850 m.s.n.m. en el Valle de La Convención, tostado medio artesanal con notas a jazmín, miel de abeja andina y bergamota.', 'Decoración', 'Agroartesanal', 45, 35, '250 gramos', 'Marrón tostado', 4.95, 'Granos arábica variedad Geisha 100% orgánicos, empaque biodegradable con válvula desgasificadora', 'CERT-CUSCO-2026-EDW01', 1, 'https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?auto=format&fit=crop&w=800&q=80', '2026-11-17 17:48:03', '2026-11-17 17:48:03', 1, 36, 20, '20% OFF');
INSERT INTO `productos` (`id`, `artesano_id`, `nombre_prod`, `descripcion_prod`, `categoria`, `subtipo`, `precio`, `stock`, `tamano`, `colores`, `puntuacion`, `materiales_origen`, `certificado_autenticidad_codigo`, `aprobado_hub`, `imagen_url`, `created_at`, `updated_at`, `en_oferta`, `precio_oferta`, `descuento_porcentaje`, `etiqueta_promocion`) VALUES (2, 1, 'Caja de Chocolates Finos de Cacao Chuncho 70% con Sal de Maras', 'Tabletas de chocolate de origen único elaborado con cacao chuncho ancestral de La Convención y cristales puros de las Salineras de Maras.', 'Decoración', 'Gourmet Artesanal', 38, 40, '150 gramos (6 piezas)', 'Cacao oscuro', 4.9, 'Cacao chuncho silvestre, panela orgánica, sal rosada de Maras cosechada a mano', 'CERT-CUSCO-2026-EDW02', 1, 'https://images.unsplash.com/photo-1549007994-cb92caebd54b?auto=format&fit=crop&w=800&q=80', '2026-11-17 17:48:03', '2026-11-17 17:48:03', 0, NULL, NULL, NULL);
INSERT INTO `productos` (`id`, `artesano_id`, `nombre_prod`, `descripcion_prod`, `categoria`, `subtipo`, `precio`, `stock`, `tamano`, `colores`, `puntuacion`, `materiales_origen`, `certificado_autenticidad_codigo`, `aprobado_hub`, `imagen_url`, `created_at`, `updated_at`, `en_oferta`, `precio_oferta`, `descuento_porcentaje`, `etiqueta_promocion`) VALUES (3, 1, 'Camino de Mesa Telar Andino Valle Sagrado', 'Camino de mesa tejido en telar artesanal de pedal por tejedores de la red de Don Edwin. Diseños geométricos que representan las terrazas agrícolas de Pisac.', 'Textiles', 'Decoración', 120, 12, '180 x 35 cm', 'Ocre tierra, Mostaza y Carbón', 4.88, 'Fibra de alpaca con mezcla de algodón orgánico teñido con tintes vegetales', 'CERT-CUSCO-2026-EDW03', 1, 'https://images.unsplash.com/photo-1606760227091-3dd870d97f1d?auto=format&fit=crop&w=800&q=80', '2026-11-17 17:48:03', '2026-11-17 17:48:03', 0, NULL, NULL, NULL);
INSERT INTO `productos` (`id`, `artesano_id`, `nombre_prod`, `descripcion_prod`, `categoria`, `subtipo`, `precio`, `stock`, `tamano`, `colores`, `puntuacion`, `materiales_origen`, `certificado_autenticidad_codigo`, `aprobado_hub`, `imagen_url`, `created_at`, `updated_at`, `en_oferta`, `precio_oferta`, `descuento_porcentaje`, `etiqueta_promocion`) VALUES (4, 2, 'Collar Chakana Cósmica en Plata 950 y Crisocola', 'Dije ceremonial de la cruz andina Chakana finamente repujado en plata peruana ley 950 con incrustación central de piedra crisocola andina.', 'Platería', 'Accesorios', 280, 8, 'Dije 3.5 cm / Cadena 50 cm', 'Plata brillante y Turquesa andino', 5, 'Plata certificada ley 950 de Huancavelica, piedra crisocola natural pulida a mano en taller de San Blas', 'CERT-CUSCO-2026-MPB01', 1, 'https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?auto=format&fit=crop&w=800&q=80', '2026-11-17 17:48:03', '2026-11-17 17:48:03', 1, 238, 15, 'Oferta Especial');
INSERT INTO `productos` (`id`, `artesano_id`, `nombre_prod`, `descripcion_prod`, `categoria`, `subtipo`, `precio`, `stock`, `tamano`, `colores`, `puntuacion`, `materiales_origen`, `certificado_autenticidad_codigo`, `aprobado_hub`, `imagen_url`, `created_at`, `updated_at`, `en_oferta`, `precio_oferta`, `descuento_porcentaje`, `etiqueta_promocion`) VALUES (5, 2, 'Aretes Filigrana Sol de San Blas en Plata 950', 'Aretes colgantes trabajados en técnica milimétrica de filigrana cusqueña, con detalles de hojas de coca y rayos solares incaicos.', 'Platería', 'Accesorios', 195, 15, '4.2 cm de largo', 'Plata 950 bruñida', 4.92, 'Hilos de plata 950 trefilados y soldados a mano con fuelle tradicional', 'CERT-CUSCO-2026-MPB02', 1, 'https://images.unsplash.com/photo-1630019852942-f89202989a59?auto=format&fit=crop&w=800&q=80', '2026-11-17 17:48:03', '2026-11-17 17:48:03', 0, NULL, NULL, NULL);
INSERT INTO `productos` (`id`, `artesano_id`, `nombre_prod`, `descripcion_prod`, `categoria`, `subtipo`, `precio`, `stock`, `tamano`, `colores`, `puntuacion`, `materiales_origen`, `certificado_autenticidad_codigo`, `aprobado_hub`, `imagen_url`, `created_at`, `updated_at`, `en_oferta`, `precio_oferta`, `descuento_porcentaje`, `etiqueta_promocion`) VALUES (6, 2, 'Cáliz Virreinal Repujado estilo Barroco Cusqueño', 'Pieza exclusiva de orfebrería de exhibición. Réplica fiel del arte colonial virreinal con hojas de acanto y querubines andinos.', 'Platería', 'Decoración', 650, 3, 'Alto 22 cm, Base 10 cm', 'Plata envejecida patinada', 5, 'Plata maciza 950, técnica de cincelado y pátina de óxido natural', 'CERT-CUSCO-2026-MPB03', 1, 'https://images.unsplash.com/photo-1582738411706-bfc8e691d1c2?auto=format&fit=crop&w=800&q=80', '2026-11-17 17:48:03', '2026-11-17 17:48:03', 0, NULL, NULL, NULL);
INSERT INTO `productos` (`id`, `artesano_id`, `nombre_prod`, `descripcion_prod`, `categoria`, `subtipo`, `precio`, `stock`, `tamano`, `colores`, `puntuacion`, `materiales_origen`, `certificado_autenticidad_codigo`, `aprobado_hub`, `imagen_url`, `created_at`, `updated_at`, `en_oferta`, `precio_oferta`, `descuento_porcentaje`, `etiqueta_promocion`) VALUES (7, 3, 'Poncho Andino Ceremonial en Lana 100% Baby Alpaca', 'Poncho tradicional de alta montaña tejido con telar de cintura (awaq), con iconografía de las constelaciones andinas y lagunas sagradas de Chinchero.', 'Textiles', 'Ropa', 420, 5, '120 x 140 cm (Estándar)', 'Rojo cochinilla, Añil y Nogal', 4.98, 'Lana 100% Baby Alpaca virgen esquilada responsablemente, teñida con insecto de cochinilla silvestre y flor de qolle', 'CERT-CUSCO-2026-MHC01', 1, 'https://images.unsplash.com/photo-1590736969955-71cc94801759?auto=format&fit=crop&w=800&q=80', '2026-11-17 17:48:03', '2026-11-18 05:19:00', 1, 336, 20, 'Promoción Exclusiva');
INSERT INTO `productos` (`id`, `artesano_id`, `nombre_prod`, `descripcion_prod`, `categoria`, `subtipo`, `precio`, `stock`, `tamano`, `colores`, `puntuacion`, `materiales_origen`, `certificado_autenticidad_codigo`, `aprobado_hub`, `imagen_url`, `created_at`, `updated_at`, `en_oferta`, `precio_oferta`, `descuento_porcentaje`, `etiqueta_promocion`) VALUES (8, 3, 'Chalina Clásica Extra Suave en Baby Alpaca Natural', 'Chalina de textura sedosa y calidez térmica inigualable sin peso excesivo. Teñida con tonos naturales sin químicos sintéticos.', 'Textiles', 'Accesorios', 160, 20, '190 x 30 cm con flecos trenzados', 'Vicuña natural y Crema andino', 4.94, '100% fibra de alpaca seleccionada a mano, tintes orgánicos de hojas de chilca', 'CERT-CUSCO-2026-MHC02', 1, 'https://images.unsplash.com/photo-1520903920243-00d872a2d1c9?auto=format&fit=crop&w=800&q=80', '2026-11-17 17:48:03', '2026-11-17 17:48:03', 0, NULL, NULL, NULL);
INSERT INTO `productos` (`id`, `artesano_id`, `nombre_prod`, `descripcion_prod`, `categoria`, `subtipo`, `precio`, `stock`, `tamano`, `colores`, `puntuacion`, `materiales_origen`, `certificado_autenticidad_codigo`, `aprobado_hub`, `imagen_url`, `created_at`, `updated_at`, `en_oferta`, `precio_oferta`, `descuento_porcentaje`, `etiqueta_promocion`) VALUES (9, 3, 'Cojín Étnico Pallay Chinchero con Flecos', 'Funda de cojín decorativo con bordados finos de fauna andina (cóndor, vicuña y picaflor) y grecas de protección comunal.', 'Textiles', 'Decoración', 95, 14, '45 x 45 cm', 'Terracota, Ocre y Azul andino', 4.87, 'Lana de alpaca y ovino criollo, cremallera oculta y forro de liencillo de algodón', 'CERT-CUSCO-2026-MHC03', 1, 'https://images.unsplash.com/photo-1584100936595-c0654b55a2e2?auto=format&fit=crop&w=800&q=80', '2026-11-17 17:48:03', '2026-11-17 17:48:03', 0, NULL, NULL, NULL);
INSERT INTO `productos` (`id`, `artesano_id`, `nombre_prod`, `descripcion_prod`, `categoria`, `subtipo`, `precio`, `stock`, `tamano`, `colores`, `puntuacion`, `materiales_origen`, `certificado_autenticidad_codigo`, `aprobado_hub`, `imagen_url`, `created_at`, `updated_at`, `en_oferta`, `precio_oferta`, `descuento_porcentaje`, `etiqueta_promocion`) VALUES (10, 2, 'Torito de Pucará Ceremonial Policromado en Arcilla', 'Símbolo andino de prosperidad, fertilidad y protección del hogar. Pintado a mano con pigmentos minerales tradicionales y barniz natural.', 'Cerámica', 'Decoración', 85, 17, 'Alto 18 cm, Largo 15 cm', 'Tierra roja, Blanco tiza y Dorado', 4.96, 'Arcilla cusqueña cocida a leña en horno tradicional, pigmentos minerales andinos', 'CERT-CUSCO-2026-CER01', 1, 'https://images.unsplash.com/photo-1578749556568-bc2c40e68b61?auto=format&fit=crop&w=800&q=80', '2026-11-17 17:48:03', '2026-11-18 05:19:00', 1, 68, 20, 'Oferta Pisac');
