INSERT INTO `mensajes` (`id`, `conversacion_id`, `remitente_id`, `mensaje`, `leido`, `leido_at`, `created_at`, `updated_at`) VALUES (1, 1, 2, '¡Hola maestro Edwin! He visto su Poncho Tradicional Chinchero en el catálogo. ¿Sería posible tejerlo con 10 cm adicionales de largo para mi esposo en París?', 1, NULL, '2026-11-17 17:23:04', '2026-11-17 17:48:04');
INSERT INTO `mensajes` (`id`, `conversacion_id`, `remitente_id`, `mensaje`, `leido`, `leido_at`, `created_at`, `updated_at`) VALUES (2, 1, 3, '¡Allianllachu Sophie! Con mucho gusto. Al ser tejido a mano en telar de cuatro estacas con pura lana de alpaca, puedo añadirle los 10 cm respetando los pallays tradicionales de Chinchero. Tomará unos 3 a 4 días en mi taller antes de llevarlo al HUB de acopio.', 1, NULL, '2026-11-17 17:30:04', '2026-11-17 17:48:04');
INSERT INTO `mensajes` (`id`, `conversacion_id`, `remitente_id`, `mensaje`, `leido`, `leido_at`, `created_at`, `updated_at`) VALUES (3, 1, 2, '¡Maravilloso maestro! Ya he procesado la compra y solicité el empaque de regalo artesanal con tarjeta QR para enviárselo directamente a mi familia.', 1, NULL, '2026-11-17 17:38:04', '2026-11-17 17:48:04');
INSERT INTO `mensajes` (`id`, `conversacion_id`, `remitente_id`, `mensaje`, `leido`, `leido_at`, `created_at`, `updated_at`) VALUES (4, 1, 3, 'Perfecto Sophie. Ya tengo la orden visible en mi panel con las instrucciones del regalo y el código QR listo para imprimir y adjuntar. ¡Sumaq sonqowan!', 0, NULL, '2026-11-17 17:45:04', '2026-11-17 17:48:04');
